+/// Trusted producer failure, distinct from a caller's ordinary invalid input.
+pub(crate) fn invariant(site: &'static str) -> GameError {
+    reject(BattleRuntimeFault {
+        code: RuntimeFaultCode::Invariant,
+        site,
+        limit: None,
+        requested: None,
+    })
+}
